#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
#include <utility>
using namespace std;

int main(){
double token[2][2]={{1,0},{0,1}},value[2]={2,5};
for(int query=0;query<2;query++){
    double score[2],largest=-1e100;
    for(int key=0;key<2;key++){
        score[key]=(token[query][0]*token[key][0]+token[query][1]*token[key][1])/sqrt(2.0);
        largest=max(largest,score[key]);
    }
    double weights[2],sum=0;
    for(int key=0;key<2;key++){weights[key]=exp(score[key]-largest);sum+=weights[key];}
    double output=0;
    for(int key=0;key<2;key++)output+=weights[key]/sum*value[key];
    cout<<query<<" "<<output<<"\n";
}
return 0;
}

